(function(){
'use strict';
const e=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),q=s=>document.querySelector(s);
const KEY='course-study-v1';let record={pages:{},chapters:{},last:{}},sourceURL=null;
try{const v=JSON.parse(localStorage.getItem(KEY));if(v&&v.pages&&v.chapters)record=v;}catch{}
function save(){try{localStorage.setItem(KEY,JSON.stringify(record));return true;}catch{if(q('#cs-status'))q('#cs-status').textContent='저장하지 못했습니다. 브라우저 저장 공간을 확인하세요.';return false;}}
function info(c,ms,number){const p=location.hash.split('/'),last=record.last?.[c.id],m=ms.find(m=>m.id===decodeURIComponent(p[4]||last?.material||''))||ms[0],built=window.COURSE_CHAPTERS.find(ch=>ch.id===m?.chapter),custom=record.chapters[m?.id]||{};const count=built?.pages.length||custom.count||m?.pages||1,n=Math.max(1,Math.min(count,number||Number(p[5])||(!p[4]&&last?.material===m?.id?last.page:(built?.startPage||1))||1));const id=`${c.id}:${m?.id}:${n}`,saved=record.pages[id]||{},base=built?.pages[n-1]||{page:n,title:`${n}쪽`,kind:'lesson',text:'',explanation:'이 자료는 직접 등록한 원문입니다. 아래 원문을 읽고 페이지 정리에서 근거가 있는 해설과 예제를 작성하세요. 자동 해설·퀴즈는 생성하지 않습니다.'};return{m,built,custom,count,n,id,saved,page:{...base,...saved.edit}};}
function href(c,m,n){return `#/course/${encodeURIComponent(c.id)}/textbook/${encodeURIComponent(m.id)}/${n}`;}
function html(c,ms,number){if(!ms.length)return '<section class="s-empty"><h2>첫 강의자료를 등록해 주세요</h2><p>강의자료 탭에서 PDF를 보관한 뒤 챕터와 페이지를 정리할 수 있습니다.</p></section>';
 const {m,built,custom,count,n,id,saved,page}=info(c,ms,number),structural=page.kind==='structure',quiz=!structural&&page.quiz,stats=Object.entries(record.pages).filter(([k])=>k.startsWith(c.id+':'));
 return `<section class="cs-reader"><div class="cs-toolbar"><label>챕터 선택<select id="cs-chapter">${ms.map(x=>`<option value="${e(x.id)}" ${m.id===x.id?'selected':''}>${e(record.chapters[x.id]?.title||x.title)}</option>`).join('')}</select></label><label>페이지<select id="cs-page">${Array.from({length:count},(_,i)=>`<option value="${i+1}" ${n===i+1?'selected':''}>${i+1} / ${count}</option>`).join('')}</select></label><button id="cs-previous" class="s-btn" ${n===1?'disabled':''}>← 이전</button><button id="cs-next" class="s-btn" ${n===count?'disabled':''}>다음 →</button></div><p class="s-muted">${e(custom.title||m.title)} · PDF ${n} / ${count}쪽 · 이 과목 학습 완료 ${stats.filter(([,v])=>v.done).length} / ${ms.reduce((total,x)=>total+(x.pages||record.chapters[x.id]?.count||1),0)}쪽</p><div class="cs-layout"><details class="cs-toc" ><summary class="cs-toc-toggle">페이지 목차·검색 펼치기</summary><label>페이지 검색<input id="cs-search" type="search" placeholder="제목 · 원문 · 번호"></label><label><input type="checkbox" id="cs-wrongs"> 오답만 보기</label><nav id="cs-list" aria-label="챕터 페이지">${Array.from({length:count},(_,i)=>{const num=i+1,base=built?.pages[i],r=record.pages[`${c.id}:${m.id}:${num}`]||{},p={...base,...r.edit};return `<a href="${href(c,m,num)}" data-search="${e((num+' '+(p.title||'')+' '+(p.text||'')).toLowerCase())}" data-wrong="${r.answer!==undefined&&p.quiz&&r.answer!==0?'yes':'no'}" ${num===n?'aria-current="page"':''}><span>${num}</span><span>${e(p.title||`${num}쪽`)}${p.kind==='structure'?' · 안내':''}</span><span>${r.done?'✓':''}</span></a>`;}).join('')}</nav></details><article class="cs-lesson"><div class="cs-pageheading"><div><span class="s-status ${structural?'':'ready'}">${structural?'안내 페이지 · 퀴즈 없음':'개념 학습 · '+e(page.role||'개념 학습')}</span><h2>${e(page.title)}</h2></div><button id="cs-complete" class="s-btn ${saved.done?'teal':''}">${saved.done?'✓ 학습 완료':'학습 완료 표시'}</button></div><nav aria-label="페이지 학습 순서"><a href="#cs-lab-anchor" id="cs-jump-lab">직접 실험</a><a href="#cs-quiz-anchor" id="cs-jump-quiz">문제 풀기</a><a href="#cs-source-anchor" id="cs-jump-source">원문·근거</a></nav>${examRange(c,m,n)}<section class="cs-explain"><h3>무엇이고 왜 필요한가</h3><p>${e(page.explanation)}</p><small>${built?('해설·예제·도식은 원문 개념을 풀어 쓴 보충 설명입니다. 교수자의 구두 발언을 재현하지 않습니다.'):'직접 정리한 해설은 원문과 비교해 확인하세요.'}</small></section>${deepLesson(page)}<div id="cs-lab-anchor"></div>${built&&!structural?'<div id="cs-interactive"></div>':''}${quiz?`<section id="cs-quiz-anchor" class="cs-quiz"><h3>개념 확인</h3><form id="cs-quiz"><fieldset><legend>${e(quiz[0])}</legend>${quiz[1].map((v,i)=>({v,i})).sort((a,b)=>((a.i+n)%quiz[1].length)-((b.i+n)%quiz[1].length)).map(({v,i})=>`<label><input name="answer" type="radio" value="${i}" ${saved.answer===i?'checked':''} required> ${e(v)}</label>`).join('')}</fieldset><button class="s-btn teal" type="submit">정답 확인</button></form><div id="cs-feedback" role="status">${saved.answer!==undefined?feedback(quiz,saved.answer,page.quizReasons):''}</div></section>`:''}${evidence(page,m,n)}<details id="cs-source-anchor" class="cs-source" open><summary>원문 대조 · PDF ${n}쪽</summary>${built?.localSource?'':`<p><a id="cs-pdf" class="s-btn" ${built?`href="${e(m.url)}#page=${n}" target="_blank" rel="noopener"`:''}>원본 PDF에서 이 페이지 열기 ↗</a></p>`}${page.image?`<a href="${e(page.image)}" target="_blank" rel="noopener"><img src="${e(page.image)}" alt="${e(m.title)} PDF ${n}쪽 원문" loading="lazy"></a>`:`<div id="cs-upload-preview"><button class="s-btn" id="cs-load-file">${built?.localSource?'영어 원문 PDF 열기':'보관한 원문 열기'}</button></div>`}${page.text?`<details><summary>검색용 추출 텍스트</summary><pre>${e(page.text)}</pre><p>그림·수식·들여쓰기는 위 원문 이미지와 비교하세요.</p></details>`:''}</details><label class="cs-note">내 학습 메모<textarea id="cs-note" rows="4" placeholder="헷갈린 점, 나만의 예시">${e(saved.note||'')}</textarea></label><p id="cs-status" role="status"></p><details class="cs-organizer"><summary>챕터·페이지 정리</summary><p>제목·쪽수·해설을 직접 정리합니다. 표지·목차·참고문헌은 안내 페이지로 지정하면 퀴즈가 표시되지 않습니다.</p><form id="cs-edit"><label>챕터 제목<input name="chapter" maxlength="180" value="${e(custom.title||m.title)}" required></label>${built?'':`<label>PDF 총 쪽수<input name="count" type="number" min="1" max="10000" value="${count}" required></label>`}<label>이 페이지 제목<input name="title" maxlength="180" value="${e(page.title)}" required></label><label>페이지 종류<select name="kind"><option value="lesson" ${!structural?'selected':''}>학습 내용</option><option value="structure" ${structural?'selected':''}>표지·목차·참고문헌·안내</option></select></label><label>원문에 근거한 쉬운 해설<textarea name="explanation" rows="5" maxlength="12000">${e(page.explanation)}</textarea></label><label>확인 질문 · 선택<input name="question" maxlength="500" value="${e(page.quiz?.[0]||'')}"></label><label>선택지 · 한 줄에 하나, 첫 줄이 정답<textarea name="options" rows="3" maxlength="2000">${e(page.quiz?.[1]?.join('\n')||'')}</textarea></label><label>정답 해설<input name="why" maxlength="2000" value="${e(page.quiz?.[2]||'')}"></label><button class="s-btn teal">정리 저장</button></form></details><div class="cs-toolbar"><button id="cs-export" class="s-btn">교재 정리·기록 내보내기</button><label class="s-btn">불러오기<input id="cs-import" type="file" accept="application/json" hidden></label></div><p class="s-muted">정리·진도·업로드 파일은 이 브라우저에 저장됩니다. 내보내기에는 PDF 파일이 포함되지 않습니다.</p></article></div></section>`;
}
function feedback(quiz,a,reasons){return `<p class="cs-result">${a===0?'정답입니다.':'다시 확인해 보세요.'} 정답: ${e(quiz[1][0])}</p><p>${e(quiz[2])}</p>${reasons?`<details class="cs-feedback-detail" open><summary>선택지별 이유</summary><ul>${quiz[1].map((v,i)=>`<li><b>${e(v)}</b> — ${e(reasons[i]||quiz[2])}</li>`).join('')}</ul></details>`:''}`;}
function regexLab(){return `<section class="cs-lab"><h3>정규표현식 직접 확인</h3><label>강의 패턴<select id="cs-pattern"><option value="digits">[0-9]+</option><option value="id">[a-zA-Z_][a-zA-Z0-9_]*</option><option value="mail">[a-zA-Z0-9]+@[a-zA-Z0-9]+\\.[a-zA-Z]{2,}</option></select></label><label>검사할 문자열<input id="cs-string" value="123" maxlength="200"></label><p id="cs-match" role="status">문자열을 바꿔 전체 일치를 확인하세요.</p></section>`;}
function treeLab(){return `<section class="cs-lab"><h3>AST 구조 비교 · 3 + 4 * 5</h3><label>묶는 방법<select id="cs-tree-choice"><option value="normal">3 + (4 * 5) · 곱셈 먼저</option><option value="other">(3 + 4) * 5 · 덧셈 먼저</option></select></label><pre id="cs-tree">    +
   / \\
  3   *
     / \\
    4   5
결과: 23</pre><p>두 구조가 모두 허용되면 모호한 문법입니다. 우선순위 규칙으로 하나를 선택합니다.</p></section>`;}
function rerender(){window.dispatchEvent(new HashChangeEvent('hashchange'));}
function bind(c,ms,host=document,number){if(!ms.length)return;const q=s=>host.querySelector(host.dataset?.prefix?s.replace(/#([\w-]+)/g,(_,id)=>'#'+host.dataset.prefix+id):s);const {m,built,count,n,id,saved,page}=info(c,ms,number);if(sourceURL){URL.revokeObjectURL(sourceURL);sourceURL=null;}
const update=change=>{const before=structuredClone(record);record.pages[id]??={};change(record.pages[id]);if(!save()){record=before;return false;}return true;};
if(!number){record.last??={};record.last[c.id]={material:m.id,page:n};save();}
if(q('#cs-interactive')&&!number)window.PLLab.mount(q('#cs-interactive'),m.chapter,n,(key,result)=>update(v=>{v.labs??={};v.labs[key]=result;}));
for(const [button,target] of [['lab','cs-lab-anchor'],['quiz','cs-quiz-anchor'],['source','cs-source-anchor']]){const b=q('#cs-jump-'+button);if(b){b.hidden=button==='lab'?!q('#cs-interactive')||!window.PLLab.mode(m.chapter,n):!q('#'+target);b.onclick=ev=>{ev.preventDefault();q('#'+target)?.scrollIntoView({behavior:'smooth',block:'start'});};}}
q('#cs-chapter').onchange=ev=>location.hash=href(c,ms.find(x=>x.id===ev.target.value),1);q('#cs-page').onchange=ev=>location.hash=href(c,m,+ev.target.value);q('#cs-previous').onclick=()=>location.hash=href(c,m,n-1);q('#cs-next').onclick=()=>location.hash=href(c,m,n+1);
const filter=()=>{let visible=0;host.querySelectorAll(host.dataset?.prefix?'[data-original-id=cs-list] a':'#cs-list a').forEach(a=>{a.hidden=!(a.dataset.search.includes(q('#cs-search').value.trim().toLowerCase())&&(!q('#cs-wrongs').checked||a.dataset.wrong==='yes'));if(!a.hidden)visible++;});q('#cs-status').textContent=visible?'': '조건에 맞는 페이지가 없습니다.';};q('#cs-search').oninput=filter;q('#cs-wrongs').onchange=filter;
q('#cs-complete').onclick=()=>{if(update(v=>v.done=!v.done)){const done=record.pages[id].done;q('#cs-complete').textContent=done?'✓ 학습 완료':'학습 완료 표시';q('#cs-complete').classList.toggle('teal',done);}};q('#cs-note').oninput=ev=>update(v=>v.note=ev.target.value.slice(0,20000));
if(q('#cs-quiz'))q('#cs-quiz').onsubmit=ev=>{ev.preventDefault();const answer=+new FormData(ev.target).get('answer');if(update(v=>{v.answer=answer;if(answer===0)v.done=true;})){q('#cs-feedback').innerHTML=feedback(page.quiz,answer,page.quizReasons);if(answer===0){q('#cs-complete').textContent='✓ 학습 완료';q('#cs-complete').classList.add('teal');}}};
q('#cs-edit').onsubmit=ev=>{ev.preventDefault();const f=new FormData(ev.target),options=String(f.get('options')).split('\n').map(x=>x.trim()).filter(Boolean),question=String(f.get('question')).trim();if(question&&options.length<2){q('#cs-status').textContent='질문에는 선택지를 두 개 이상 적어 주세요.';return;}const previous=structuredClone(record);record.chapters[m.id]={title:String(f.get('chapter')),count:f.get('count')?+f.get('count'):count};record.pages[id]??={};record.pages[id].edit={title:String(f.get('title')),kind:String(f.get('kind')),explanation:String(f.get('explanation')),quiz:question?[question,options,String(f.get('why'))]:null};delete record.pages[id].answer;if(save())rerender();else record=previous;};
if(q('#cs-pattern')){const run=()=>{const patterns={digits:/^[0-9]+$/,id:/^[a-zA-Z_][a-zA-Z0-9_]*$/,mail:/^[a-zA-Z0-9]+@[a-zA-Z0-9]+\.[a-zA-Z]{2,}$/};q('#cs-match').textContent=patterns[q('#cs-pattern').value].test(q('#cs-string').value)?'✓ 전체 문자열이 일치합니다.':'전체 문자열과 일치하지 않습니다.';};q('#cs-pattern').onchange=run;q('#cs-string').oninput=run;run();}
if(q('#cs-tree-choice'))q('#cs-tree-choice').onchange=ev=>q('#cs-tree').textContent=ev.target.value==='normal'?'    +\n   / \\\n  3   *\n     / \\\n    4   5\n결과: 23':'    *\n   / \\\n  +   5\n / \\\n3   4\n결과: 35';
if(q('#cs-load-file'))q('#cs-load-file').onclick=async()=>{if(built?.localSource)return window.StudyLibrary.openChapterSource(built,n);try{const db=await new Promise((resolve,reject)=>{const r=indexedDB.open('study-library-files-v1',1);r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(Error('파일 보관함을 열 수 없습니다.'));});const file=await new Promise((resolve,reject)=>{const r=db.transaction('files').objectStore('files').get(m.id);r.onsuccess=()=>r.result?resolve(r.result.file):reject(Error('원본 파일을 이 브라우저에 다시 등록해 주세요.'));r.onerror=()=>reject(Error('파일을 읽을 수 없습니다.'));});const blob=new Blob([file],{type:/\.pdf$/i.test(m.filename)?'application/pdf':file.type});sourceURL=URL.createObjectURL(blob);q('#cs-pdf').href=sourceURL+'#page='+n;q('#cs-pdf').target='_blank';if(/\.pdf$/i.test(m.filename))q('#cs-upload-preview').innerHTML=`<iframe title="보관한 PDF ${n}쪽" src="${sourceURL}#page=${n}"></iframe>`;else q('#cs-upload-preview').textContent='원본 파일 링크를 눌러 확인하세요.';}catch(err){q('#cs-status').textContent=err.message;}};
q('#cs-export').onclick=()=>{const blob=new Blob([JSON.stringify({version:1,...record},null,2)],{type:'application/json'}),a=document.createElement('a'),u=URL.createObjectURL(blob);a.href=u;a.download='course-study-backup.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),2000);};
q('#cs-import').onchange=async ev=>{const f=ev.target.files[0];if(!f)return;try{if(f.size>5e6)throw Error();const v=JSON.parse(await f.text());if(v.version!==1||!v.pages||Array.isArray(v.pages)||!v.chapters||Array.isArray(v.chapters))throw Error();for(const r of Object.values(v.pages)){if(!r||typeof r!=='object'||r.edit&&(typeof r.edit.title!=='string'||typeof r.edit.explanation!=='string'||!['structure','lesson'].includes(r.edit.kind)))throw Error();if(r.edit?.quiz&&(!Array.isArray(r.edit.quiz)||typeof r.edit.quiz[0]!=='string'||!Array.isArray(r.edit.quiz[1])||r.edit.quiz[1].length<2||!r.edit.quiz[1].every(x=>typeof x==='string')||typeof r.edit.quiz[2]!=='string'))throw Error();}for(const ch of Object.values(v.chapters)){if(!ch||typeof ch.title!=='string'||!Number.isInteger(ch.count)||ch.count<1||ch.count>10000)throw Error();}const prev=record;record={pages:{...record.pages,...v.pages},chapters:{...record.chapters,...v.chapters},last:{...record.last}};if(save())rerender();else record=prev;}catch{q('#cs-status').textContent='올바른 교재 정리 백업 파일을 선택하세요.';}};
}
function deepLesson(page){const d=page.lesson;if(!d)return '';return `<div class="cs-depth"><section><h3>구체적인 예로 읽기</h3><p>원문 개념을 풀어 쓴 예제·도식입니다. 생략·보충 표기가 포함되어 있습니다.</p><pre tabindex="0">${e(d.example)}</pre></section><section><h3>어떻게 작동하는가 · 단계별 풀이</h3><ol>${d.steps.map(t=>`<li>${e(t)}</li>`).join('')}</ol></section><section class="cs-trap"><h3>헷갈리기 쉬운 점</h3><p>${e(d.trap)}</p></section><section class="cs-exam"><h3>문제에서 구분할 기준</h3><p>${e(d.recap)}</p><small>학습용 구분 기준이며 실제 시험 출제 예고가 아닙니다.</small></section></div>`;}
function evidence(page,m,n){const r=page.review;if(!r)return `<details class="cs-evidence"><summary>원문·보충 설명의 범위</summary><p>원문: ${e(m.filename)} · PDF ${n}쪽. 아래 이미지와 PDF를 그대로 보존했습니다.</p><p>보충 설명: 본문의 쉬운 해설·풀이·교육 모델입니다. 강의의 구두 설명이나 공식 정답을 재현하지 않습니다.</p><p>이 페이지에 별도 검증 항목이 없다는 것이 오류가 없음을 보증하지 않습니다.</p></details>`;return `<details class="cs-evidence"><summary>자료 검토 · 원문 / 확인한 설명 / 강의 확인 필요</summary><h4>원문 · ${e(m.filename)} PDF ${n}쪽</h4><blockquote>${e(r.original)}</blockquote><h4>${r.url?'검증된 설명 · 외부 근거 확인':'직접 대조한 설명 · 외부 검증 완료 아님'}</h4><p>${e(r.checked)}</p><p>${e(r.label)}${r.url?` · <a href="${e(r.url)}" target="_blank" rel="noopener">확인한 근거 펼치기 ↗</a>`:''}</p><h4>강의 확인 필요</h4><p>${e(r.ask)}</p></details>`;}
function examRange(c,m,n){const parts=[];for(const [key,name] of [['mid','중간'],['final','기말']]){const ranges=c.exam?.[key]||{},text=ranges[m.id];if(!Object.keys(ranges).length){parts.push(name+': 범위 미지정');continue;}const included=text&&(text.trim()==='전체'||text.split(',').some(t=>{const[a,b]=t.trim().split('-').map(Number);return n>=a&&n<=(b||a);}));parts.push(name+': '+(included?'이 페이지 포함':'이 페이지 미포함'));}return `<p class="cs-range">시험 범위 · ${parts.join(' / ')} · <a href="#/course/${encodeURIComponent(c.id)}/exams">범위 수정</a></p>`;}
function review(c,ms){const links=[];for(const m of ms){const built=window.COURSE_CHAPTERS.find(ch=>ch.id===m.chapter),count=built?.pages.length||record.chapters[m.id]?.count||m.pages||1;for(let n=1;n<=count;n++){const r=record.pages[`${c.id}:${m.id}:${n}`],p={...built?.pages[n-1],...r?.edit};for(const a of Object.values(r?.labs||{})){if(!a.correct)links.push(`<a class="s-review-link" href="${href(c,m,n)}">예측 복습: ${e(a.question)}<small>${e(m.title)} · PDF ${n}쪽 · 예상 ${e(a.choice)} / 실제 ${e(a.expected)}</small></a>`);}if(r&&r.answer!==undefined&&r.answer!==0&&p.quiz&&p.kind!=='structure')links.push(`<a class="s-review-link" href="${href(c,m,n)}">${e(p.quiz[0])}<small>${e(m.title)} · PDF ${n}쪽</small></a>`);}}return `<section class="s-section"><h2>오답 복습</h2><p>이 과목에서 틀린 문제입니다. 다시 정답을 맞히면 목록에서 빠집니다.</p>${links.join('')||'<p>현재 복습할 오답이 없습니다.</p>'}<a class="s-btn teal" href="#/course/${encodeURIComponent(c.id)}/textbook">학습 교재 열기</a></section>`;}
window.CourseStudy={html,bind,review,info,remember(c,ms,n){const {m}=info(c,ms,n);record.last??={};record.last[c.id]={material:m.id,page:n};save();},saveLab(c,ms,n,key,result){const {id}=info(c,ms,n);record.pages[id]??={};record.pages[id].labs??={};record.pages[id].labs[key]=result;save();}};
})();
